#include <iostream>

struct NumberList {
    static constexpr int capacity = 8;
    int values[capacity];
    int length;

    bool has_elements() {
        return length > 0;
    }
};

int main() {
    // 测试输入留空。预期输出：容量 8、表长 4、首个元素 10。
    NumberList list{{10, 20, 30, 40}, 4};
    std::cout << "容量：" << list.capacity << '\n';
    std::cout << "表长：" << list.length << '\n';
    if (list.has_elements()) {
        std::cout << "首个元素：" << list.values[0] << '\n';
    }
    return 0;
}
